param([string]$GowinBin = 'D:\apps\Gowin\Gowin_V1.9.12.03_x64\IDE\bin')
$ErrorActionPreference = 'Stop'
$rootPath = Split-Path -Parent $PSScriptRoot
New-Item -ItemType Directory -Path (Join-Path $rootPath 'tmp') -Force | Out-Null
Push-Location -LiteralPath $rootPath
try {
    # Gowin's own detailed reports are saved under impl/.
    $buildStartedUtc = (Get-Date).ToUniversalTime()
    & (Join-Path $GowinBin 'gw_sh.exe') build.tcl > (Join-Path $rootPath 'tmp\gowin_build.log') 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Gowin failed, exit code $LASTEXITCODE" }
    $bitstream = Join-Path $rootPath 'impl\pnr\acg720_m10_hdmi.fs'
    if (!(Test-Path -LiteralPath $bitstream)) { throw 'No bitstream produced; inspect impl logs.' }
    if ((Get-Item -LiteralPath $bitstream).LastWriteTimeUtc -lt $buildStartedUtc) { throw 'Bitstream was not regenerated by this build.' }
    & python (Join-Path $PSScriptRoot 'check_timing.py')
    if ($LASTEXITCODE -ne 0) { throw 'Gowin timing failed; inspect impl/pnr/acg720_m10_hdmi.tr.html.' }
    Write-Output "Bitstream: $bitstream"
} finally {
    Pop-Location
}
